  "base1-93": {"id":"base1-93","name":"Gust of Wind","set":"base1","num":"93","rarity":"Common","artist":"Keiji Kinebuchi","kind":"trainer","sub":"Trainer","text":"Choose 1 of your opponent's Benched Pokémon and switch it with his or her Active Pokémon."},
