  "base2-33": {"id":"base2-33","name":"Butterfree","set":"base2","num":"33","rarity":"Uncommon","artist":"Kagemaru Himeno","kind":"pokemon","stage":"Stage 2","hp":70,"type":"G","evolvesFrom":"Metapod","wkType":"R","wkVal":"x2","rsType":"F","rsVal":"-30","retreat":0,"attacks":[{"name":"Whirlwind","cost":"CC","dmg":"20","text":"If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with the Defending Pokémon. (Do the damage before switching the Pokémon.)"},{"name":"Mega Drain","cost":"GGGG","dmg":"40","text":"Remove a number of damage counters from Butterfree equal to half the damage done to the Defending Pokémon (after applying Weakness and Resistance) (rounded up to the nearest 10)."}],"power":null,"dex":12,"flavor":"In battle, it flaps its wings at high speed to release highly toxic dust into the air."},
  "base2-34": {"id":"base2-34","name":"Dodrio","set":"base2","num":"34","rarity":"Uncommon","artist":"Mitsuhiro Arita","kind":"pokemon","stage":"Stage 1","hp":70,"type":"C","evolvesFrom":"Doduo","wkType":"L","wkVal":"x2","rsType":"F","rsVal":"-30","retreat":0,"attacks":[{"name":"Rage","cost":"CCC","dmg":"10+","text":"Does 10 damage plus 10 more damage for each damage counter on Dodrio."}],"power":{"kind":"Pokémon Power","name":"Retreat Aid","text":"As long as Dodrio is Benched, pay Colorless less to retreat your Active Pokémon."},"dex":85,"flavor":"Uses its three brains to execute complex plans. While two heads sleep, one head stays awake."},
