  "base2-63": {"id":"base2-63","name":"Venonat","set":"base2","num":"63","rarity":"Common","artist":"Mitsuhiro Arita","kind":"pokemon","stage":"Basic","hp":40,"type":"G","evolvesFrom":"","wkType":"R","wkVal":"x2","rsType":"","rsVal":"","retreat":1,"attacks":[{"name":"Stun Spore","cost":"G","dmg":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Leech Life","cost":"GC","dmg":"10","text":"Remove a number of damage counters from Venonat equal to the damage done to the Defending Pokémon (after applying Weakness and Resistance)."}],"power":null,"dex":48,"flavor":"Lives in the shadows of tall trees where it eats insects. It is attracted by light at night."},
  "base2-64": {"id":"base2-64","name":"Poké Ball","set":"base2","num":"64","rarity":"Common","artist":"Keiji Kinebuchi","kind":"trainer","sub":"Trainer","text":"Flip a coin. If heads, you may search your deck for any Basic Pokémon or Evolution card. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward."},
  "base3-1": {"id":"base3-1","name":"Aerodactyl","set":"base3","num":"1","rarity":"Rare Holo","artist":"Kagemaru Himeno","kind":"pokemon","stage":"Stage 1","hp":60,"type":"F","evolvesFrom":"Mysterious Fossil","wkType":"G","wkVal":"x2","rsType":"F","rsVal":"-30","retreat":2,"attacks":[{"name":"Wing Attack","cost":"CCC","dmg":"30","text":""}],"power":{"kind":"Pokémon Power","name":"Prehistoric Power","text":"No more Evolution cards can be played. This power stops working while Aerodactyl is Asleep, Confused, or Paralyzed."},"dex":142,"flavor":"A ferocious prehistoric Pokémon that goes for the enemy's throat with its serrated saw-like fangs."},
